old_projection=saved['accounting']
diffkeys=sorted(k for k in set(projected_normalized)|set(old_projection) if projected_normalized.get(k)!=old_projection.get(k))
comparison={'original_status':old_projection['status'],'original_receipt':saved['receipt_source'],'original_exact_helper_result_sha256':old_projection['exact_helper_result_sha256'],'normalized_derivative_exact_helper_result_sha256':normalized_sha,'normalization_removed_only':['compaction_context_derivative','source_sha256 entries absent from original source map'],'original_source_map_is_identical_subset':source_subset,'added_source_paths':sorted(set(sources)-set(old_sources)),'normalized_full_result_sha256_equals_original':normalized_sha==old_projection['exact_helper_result_sha256'],'normalized_projection_equals_original':projected_normalized==old_projection,'differing_original_top_level_result_keys':diffkeys,'equality_required':old_projection['status']=='validated','original_unknown_is_not_zero_filled':old_projection['status']!='validated'}
checks={'frozen_inputs_count':len(frozen['files']),'frozen_and_declared_inputs_start_match':True,'prehashed_source_count':len(refs),'returned_source_count':len(sources),'returned_sources_not_prehashed':sorted(set(sources)-set(refs)),'returned_sources_endpoint_errors':[],'all_declared_and_frozen_endpoint_errors':[],'started_at':started_at,'finished_at':finished_at,'elapsed_seconds':round(elapsed,3)}
for p,digest in sources.items():
 try:
  if sha(Path(p).read_bytes())!=digest:checks['returned_sources_endpoint_errors'].append(p)
 except OSError as error:checks['returned_sources_endpoint_errors'].append({'path':p,'error':str(error)})
for p,digest in refs.items():
 try:
  if sha(Path(p).read_bytes())!=digest:checks['all_declared_and_frozen_endpoint_errors'].append(p)
 except OSError as error:checks['all_declared_and_frozen_endpoint_errors'].append({'path':p,'error':str(error)})
checks['returned_sources_endpoint_match']=not checks['returned_sources_endpoint_errors']
checks['all_declared_and_frozen_endpoint_match']=not checks['all_declared_and_frozen_endpoint_errors']
checks['returned_sources_all_prehashed']=not checks['returned_sources_not_prehashed']
receipt={'scope_sha256':scope_sha,'kind':'run','original_entry':entry,'accounting':project(full),'original_comparison':comparison,'replay_checks':checks}
print(json.dumps({'receipt':receipt,'response_ownership':ownership,'output_path':str(outpath)},separators=(',',':')))
